// Writes src/content/short/index.ts, importing every course file in src/content/short.
import { readdirSync, writeFileSync } from "node:fs";
const dir = "src/content/short";
const files = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
const id = (f) => "c_" + f.replace(/\.json$/, "").replace(/[^a-z0-9]/gi, "_");
const lines = [
  "// Generated by scripts/short-index.mjs. Do not edit by hand.",
  'import type { ShortCourse } from "./types";',
  ...files.map((f) => `import ${id(f)} from "./${f}";`),
  "",
  `export const shortCourses = [${files.map(id).join(", ")}] as ShortCourse[];`,
  "",
];
writeFileSync(`${dir}/index.ts`, lines.join("\n"));
console.log(`Indexed ${files.length} short course files.`);
